def select_next_node(current_node, depot, unvisited_nodes, rest_capacity, demands, distance_matrix):
    cur = distance_matrix[current_node]
    dep = distance_matrix[depot]
    saving = cur[depot] + dep[unvisited_nodes] - cur[unvisited_nodes]
    top = saving.max()
    tied = unvisited_nodes[saving == top]
    if tied.size > 1:
        return int(tied[np.argmax(dep[tied])])
    return int(unvisited_nodes[np.argmax(saving)])

def select_next_node(current_node, depot, unvisited_nodes, rest_capacity, demands, distance_matrix):
    cur = distance_matrix[current_node][unvisited_nodes]
    dep = distance_matrix[depot][unvisited_nodes]
    score = cur - 2.0 * dep + 0.02 * demands[unvisited_nodes]
    return int(unvisited_nodes[np.argmin(score)])

def solve_tsp_nn_2opt(dmat: np.ndarray, *, time_budget_ms: float | None = 500.0, max_passes: int = 200) -> tuple[list[int], dict[str, Any]]:
    t0 = time.perf_counter()
    deadline = (t0 + time_budget_ms / 1000.0) if time_budget_ms is not None else None
    tour, meta = solve_tsp_nn(dmat, time_budget_ms=time_budget_ms)
    if meta.get("budget_exhausted") or len(tour) < 4:
        return tour, {**meta, "two_opt_moves": 0}
    n = len(tour)
    moves = 0
    passes = 0
    budget_exhausted = False
    while passes < max_passes:
        passes += 1
        improved = False
        for i in range(n - 2):
            if deadline is not None and (i & 31) == 0 and time.perf_counter() > deadline:
                budget_exhausted = True
                break
            a = tour[i]
            b = tour[i + 1]
            d_ab = float(dmat[a, b])
            j_end = n - 1 if i == 0 else n
            for j in range(i + 2, j_end):
                c = tour[j]
                d = tour[(j + 1) % n]
                delta = float(dmat[a, c]) + float(dmat[b, d]) - d_ab - float(dmat[c, d])
                if delta < -1e-9:
                    tour[i + 1 : j + 1] = tour[i + 1 : j + 1][::-1]
                    moves += 1
                    improved = True
                    b = tour[i + 1]
                    d_ab = float(dmat[a, b])
        if budget_exhausted or not improved:
            break
    if not budget_exhausted and passes >= max_passes:
        budget_exhausted = True
    return tour, {"two_opt_moves": moves, "passes": passes, "budget_exhausted": budget_exhausted}
